(function(){'use strict';if(!('serviceWorker' in navigator))return;window.addEventListener('load',function(){navigator.serviceWorker.getRegistrations().then(function(regs){regs.forEach(function(r){try{var url=(r.active&&r.active.scriptURL)||(r.installing&&r.installing.scriptURL)||'';if(!url)return;var isLegacyRoot=url.indexOf('/service-worker.js')!==-1&&url.indexOf('.php')===-1;var isLegacyCrm=/\/crm\/sw\.js(\?|$)/.test(url);if(isLegacyRoot||isLegacyCrm){r.unregister()}}catch(e){}})}).catch(function(){});navigator.serviceWorker.register('/service-worker.php',{scope:'/'}).then(function(reg){setInterval(function(){reg.update()},1800000)}).catch(function(){});navigator.serviceWorker.addEventListener('controllerchange',function(){window.location.reload()})})}())